import{_ as t,o as s,c as r,ah as o}from"./chunks/framework.ChH6X6u6.js";const c=JSON.parse('{"title":"Modèles de documents","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/gestion-documentaire/modeles.md","filePath":"src/guide/gestion-documentaire/modeles.md"}'),d={name:"guide/gestion-documentaire/modeles.md"};function n(a,e,l,i,u,p){return s(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="modeles-de-documents" tabindex="-1">Modèles de documents <a class="header-anchor" href="#modeles-de-documents" aria-label="Permalink to &quot;Modèles de documents&quot;">​</a></h1><p>Un <strong>modèle</strong> est un document que l&#39;établissement rédige une fois et produit ensuite pour chacun : certificat de scolarité, attestation de travail… Au moment de le produire, ERA remplit ses champs d&#39;après la fiche de la personne, le met en page sur l&#39;en-tête de l&#39;établissement et le range dans son dossier.</p><p>Les modèles sont tenus par un administrateur ou le gestionnaire documentaire, depuis l&#39;espace <strong>Documents</strong> → <strong>Modèles</strong>.</p><h2 id="rediger-un-modele" tabindex="-1">Rédiger un modèle <a class="header-anchor" href="#rediger-un-modele" aria-label="Permalink to &quot;Rédiger un modèle&quot;">​</a></h2><ol><li>Cliquez sur <strong>Nouveau modèle</strong>.</li><li>Pour partir d&#39;un texte prêt, cliquez sur <strong>Partir d&#39;un exemple</strong> : ERA remplit un certificat de scolarité, que vous adaptez.</li><li>Donnez-lui un <strong>Nom</strong> : c&#39;est aussi le titre imprimé en haut du document.</li><li>Choisissez sous quel type il est <strong>Rangé sous</strong>. Le dossier de ce type (élève, employé ou établissement) décide des champs proposés.</li><li>Rédigez le <strong>Texte</strong>. Laissez une ligne vide entre deux paragraphes.</li><li>Pour insérer un champ, placez le curseur puis cliquez sur le champ sous <strong>Insérer un champ</strong>. Il s&#39;écrit entre accolades, par exemple <code>{student.full_name}</code>.</li><li>Cliquez sur <strong>Enregistrer</strong>.</li></ol><p>L&#39;en-tête (logo, nom et coordonnées de l&#39;établissement), le titre et l&#39;espace de signature « La direction » s&#39;ajoutent d&#39;eux-mêmes : ne les écrivez pas dans le texte.</p><p>Si le texte contient un champ que le dossier du type ne propose pas (un champ d&#39;employé dans un certificat d&#39;élève, une faute de frappe), ERA refuse l&#39;enregistrement et nomme le champ en cause.</p><h3 id="les-champs" tabindex="-1">Les champs <a class="header-anchor" href="#les-champs" aria-label="Permalink to &quot;Les champs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Champ</th><th>Rempli avec</th><th>Dossiers</th></tr></thead><tbody><tr><td>Nom de l&#39;établissement</td><td>le nom de l&#39;application</td><td>tous</td></tr><tr><td>Adresse de l&#39;établissement</td><td>l&#39;adresse de <strong>Paramètres de l&#39;application</strong> → <strong>Personnalisation des reçus</strong></td><td>tous</td></tr><tr><td>Date du jour</td><td>la date où le document est produit</td><td>tous</td></tr><tr><td>Année scolaire</td><td>l&#39;année scolaire en cours</td><td>tous</td></tr><tr><td>Nom complet, Nom, Prénoms</td><td>la fiche de l&#39;élève</td><td>élève</td></tr><tr><td>Date et lieu de naissance</td><td>la fiche de l&#39;élève</td><td>élève</td></tr><tr><td>Matricule</td><td>le numéro matricule de l&#39;élève</td><td>élève</td></tr><tr><td>Classe, Site</td><td>son inscription de l&#39;année en cours</td><td>élève</td></tr><tr><td>Nom, Poste, Date d&#39;embauche, Site</td><td>la fiche de l&#39;employé</td><td>employé</td></tr></tbody></table><p>Une information absente de la fiche laisse un blanc dans le document : complétez la fiche avant de le produire.</p><h2 id="produire-un-document" tabindex="-1">Produire un document <a class="header-anchor" href="#produire-un-document" aria-label="Permalink to &quot;Produire un document&quot;">​</a></h2><ol><li>Ouvrez le dossier de la personne.</li><li>Cliquez sur <strong>Produire depuis un modèle</strong>. Le bouton n&#39;apparaît que si un modèle existe pour un type que vous pouvez déposer dans ce dossier.</li><li>Choisissez le <strong>Modèle</strong>, puis cliquez sur <strong>Produire</strong>.</li></ol><p>Le document est rangé aussitôt dans le dossier, sous le type du modèle, avec la date du jour. Il est <strong>validé</strong> directement si vous pouvez valider ce type ; sinon, il attend sa vérification comme tout dépôt. Son texte peut être retrouvé par la recherche de la page <strong>Documents</strong>.</p><p>Si le type est partagé avec les familles, le document validé apparaît aussi dans le portail de la famille et de l&#39;élève.</p><h2 id="modifier-ou-supprimer-un-modele" tabindex="-1">Modifier ou supprimer un modèle <a class="header-anchor" href="#modifier-ou-supprimer-un-modele" aria-label="Permalink to &quot;Modifier ou supprimer un modèle&quot;">​</a></h2><p><strong>Modifier</strong> change le texte pour les prochains documents produits ; ceux déjà produits ne changent pas. <strong>Supprimer</strong> retire le modèle ; les documents déjà produits restent dans leurs dossiers. Supprimer un type de documents supprime aussi ses modèles.</p>',16)])])}const g=t(d,[["render",n]]);export{c as __pageData,g as default};
